-- Lolys hosted feature repair, 2026-10-29. OWNER-RUN, not a fresh database setup.
-- Run the ENTIRE file as postgres in Supabase SQL Editor. No selection.
-- Generated by node scripts/build-hosted-features.mjs; do not edit guards.
-- BEGIN/COMMIT is atomic: a failed check cancels this repair.
begin;
set local lock_timeout = '5s';
set local statement_timeout = '120s';
set local search_path = public, extensions;

-- Included in hosted-features-APPLY.sql. Do not run fragments separately.
do $preflight$
begin
  if current_user <> 'postgres' then
    raise exception 'Run the whole repair file as postgres in Supabase SQL Editor';
  end if;
  perform pg_advisory_xact_lock(20261029, 206);
  if md5(replace(pg_get_functiondef(to_regprocedure('public.is_admin()')), chr(13), ''))
      is distinct from '352ec1b537ad23124dd3f01516b05d2e'
    or md5(replace(pg_get_functiondef(to_regprocedure('public.require_admin()')), chr(13), ''))
      is distinct from 'd21b2ddedef282e186c5e95585f231b4' then
    raise exception 'MFA helpers differ from the owner-reviewed setup. Stop; do not remove this check';
  end if;
  if to_regclass('public.customer_notifications') is not null
    or to_regclass('public.customer_suggestions') is not null
    or to_regclass('public.admin_occasion_reminders') is not null
    or exists(select 1 from pg_attribute where attrelid = 'public.profiles'::regclass
      and attname = 'avatar_url' and not attisdropped)
    or exists(select 1 from storage.buckets where id = 'avatars') then
    raise exception 'Features are already or partly installed. Run hosted-features-CHECK.sql; do not replay this repair';
  end if;
  if exists(select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname in (
      'guard_order_postal_code', 'guard_profile_postal_code', 'validate_profile_avatar',
      'cleanup_old_avatar', 'cleanup_deleted_profile_avatar', 'notify_on_order_approved',
      'notify_on_wishlist_sale', 'mark_all_notifications_read', 'submit_customer_suggestion',
      'admin_review_suggestion', 'admin_broadcast_sale_notification', 'admin_get_wishlist_demand',
      'admin_get_upcoming_occasions', 'admin_generate_occasion_reminders',
      'admin_get_occasion_reminders', 'admin_dismiss_occasion_reminder', 'admin_get_forecast_export')) then
    raise exception 'A feature function is already installed. Stop and reconcile the partial installation';
  end if;
  if to_regprocedure('public.admin_update_storefront_content(jsonb,timestamptz)') is null
    or not exists(select 1 from public.shop_settings where key = 'storefront_content'
      and is_public and jsonb_typeof(value) = 'object') then
    raise exception 'The confirmed storefront editor is not present. Check the selected Supabase project';
  end if;
  if exists(select 1 from (values ('public.profiles'), ('public.orders'), ('public.order_items'),
      ('public.products'), ('public.categories'), ('public.favorites'), ('public.shop_settings'),
      ('public.audit_log'), ('storage.objects'), ('analytics.calendar')) t(name)
    where not exists(select 1 from pg_class where oid = to_regclass(t.name) and relrowsecurity)) then
    raise exception 'A required table or its RLS is missing. Repair stopped before any changes';
  end if;
  if not exists(select 1 from storage.buckets where id = 'payment-proofs' and not public) then
    raise exception 'Payment proofs must remain in their existing private bucket';
  end if;
  if (select count(*) from public.shop_settings where key in
    ('instapay_handle', 'instapay_qr_path', 'instapay_link') and not is_public) <> 3 then
    raise exception 'The three existing InstaPay settings must be private. Stop and reconcile their permissions';
  end if;
  if exists(select 1 from public.shop_settings
    where key = 'occasion_reminder_advance_days' and (is_public or value not in ('7','14','21','30'))) then
    raise exception 'Existing reminder setting differs from the supported private configuration';
  end if;
end;
$preflight$;

-- Short locks avoid racing checkout/profile/settings writes during the atomic repair.
-- Busy production traffic causes a timeout and rollback rather than a long queue.
lock table public.profiles, public.orders, public.order_items, public.products,
  public.favorites, public.shop_settings in share row exclusive mode;

-- Validate dependencies by parsing zero-row selects; never return customer records.
do $dependencies$
begin
  perform id, role, full_name, email, phone, alt_phone, governorate_id, city, district,
    address, postal_code, floor, apartment, landmark from public.profiles limit 0;
  perform id, user_id, created_at, status, payment_status, payment_method, ship_postal_code,
    ship_name, ship_phone, ship_alt_phone, ship_city, ship_district, ship_address, ship_floor,
    ship_apartment, ship_landmark, notes, payment_reference, payment_proof_path from public.orders limit 0;
  perform order_id, product_id, quantity, unit_price from public.order_items limit 0;
  perform id, name, name_ar, category_id, price, discount_percent, final_price,
    stock_quantity, is_active, image_url, created_at from public.products limit 0;
  perform id, name, name_ar from public.categories limit 0;
  perform user_id, product_id from public.favorites limit 0;
  perform day, product_id, closing_stock, stockout_flag from analytics.stock_daily limit 0;
  perform day, ramadan, eid_fitr, eid_adha, mothers_day, valentines, black_friday,
    back_to_school from analytics.calendar limit 0;
end;
$dependencies$;

-- Hashes stay inside this transaction; no settings values or personal rows are printed.
-- No temporary table is needed, avoiding the earlier SQL Editor temp-table failure.
do $preserve$
begin
  perform set_config('lolys.feature_settings_before',
    (select md5(coalesce(jsonb_agg(to_jsonb(s) order by key)::text, '[]'))
      from public.shop_settings s where key <> 'occasion_reminder_advance_days'), true);
  perform set_config('lolys.feature_functions_before',
    (select md5(jsonb_agg(jsonb_build_object('id', p.oid, 'definition', pg_get_functiondef(p.oid),
      'acl', p.proacl, 'owner', p.proowner) order by p.oid)::text)
    from pg_proc p where p.oid in (
      to_regprocedure('public.place_order(jsonb,public.delivery_method,public.payment_method,jsonb)'),
      to_regprocedure('public.get_payment_instructions(bigint)'),
      to_regprocedure('public.admin_update_storefront_content(jsonb,timestamptz)'),
      to_regprocedure('public.is_admin()'), to_regprocedure('public.require_admin()'))), true);
end;
$preserve$;

do $known_function$
begin
  if not exists (select 1 from pg_proc where oid = to_regprocedure('public.admin_anonymize_customer(uuid)')
    and proowner = 'postgres'::regrole and prosecdef
    and proconfig = array['search_path=public']
    and md5(replace(prosrc, chr(13), '')) in ('d50dc4f2a6346e6a8ef459e4f9bde555', '925188b1baabe25ef128c490ea771ead', '2fc6a75537fbdb48e500d8c476e9b919', '2c90e52da0feba24edae894277878c7a', '6e0486dcaebc1e8bc8a85785f26a86da')) then
    raise exception 'Unrecognized admin_anonymize_customer. Stop and share the error; do not bypass this check';
  end if;
end;
$known_function$;

do $known_function$
begin
  if not exists (select 1 from pg_proc where oid = to_regprocedure('public.admin_update_setting(text,jsonb)')
    and proowner = 'postgres'::regrole and prosecdef
    and proconfig = array['search_path=public']
    and md5(replace(prosrc, chr(13), '')) in ('cc0577139fc3c2858c86c6a83cc6e5a9', '530443119a7efac973ed1203a3dea51f', 'b8c2ea34401538f7ae369c7a25b239c1', 'f603765ea296b9637ef502d5ed903762')) then
    raise exception 'Unrecognized admin_update_setting. Stop and share the error; do not bypass this check';
  end if;
end;
$known_function$;

-- T-4.08b: NOT VALID checks still apply to every UPDATE. Preserve historical
-- missing data without preventing fulfillment or unrelated profile changes.
-- Fresh databases retain orders.ship_postal_code NOT NULL from T-4.08.
alter table public.orders drop constraint if exists orders_ship_postal_code_not_null;
alter table public.profiles drop constraint if exists profiles_address_postal_code_required;

create or replace function public.guard_order_postal_code()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if tg_op = 'UPDATE' then
    if new.ship_postal_code is not distinct from old.ship_postal_code then
      return new;
    end if;
  end if;
  if new.ship_postal_code is null or new.ship_postal_code !~ '^[0-9]{5}$' then
    raise exception 'Postal code required for a new order'
      using errcode = '23514', hint = 'ORD-012';
  end if;
  return new;
end;
$$;
revoke all on function public.guard_order_postal_code() from public, anon, authenticated;
create trigger require_order_postal_code
before insert or update on public.orders
for each row execute function public.guard_order_postal_code();

create or replace function public.guard_profile_postal_code()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  -- Registration and erasure may leave the entire delivery address absent.
  if new.address is null and new.governorate_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if row(new.governorate_id, new.city, new.district, new.address,
           new.floor, new.apartment, new.landmark, new.postal_code)
       is not distinct from
       row(old.governorate_id, old.city, old.district, old.address,
           old.floor, old.apartment, old.landmark, old.postal_code) then
      return new;
    end if;
  end if;
  if new.postal_code is null or new.postal_code !~ '^[0-9]{5}$' then
    raise exception 'Postal code required for a saved address'
      using errcode = '23514', hint = 'ORD-012';
  end if;
  return new;
end;
$$;
revoke all on function public.guard_profile_postal_code() from public, anon, authenticated;
create trigger require_profile_postal_code
before insert or update on public.profiles
for each row execute function public.guard_profile_postal_code();

-- 1. Customer Notifications Table
create table if not exists public.customer_notifications (
  id uuid primary key default gen_random_uuid(),
  customer_id uuid not null references public.profiles (id) on delete cascade,
  type text not null check (type in ('wishlist_sale', 'order_approved', 'general_sale')),
  title_ar text not null check (char_length(trim(title_ar)) > 0 and char_length(title_ar) <= 120),
  title_en text not null check (char_length(trim(title_en)) > 0 and char_length(title_en) <= 120),
  message_ar text not null check (char_length(trim(message_ar)) > 0 and char_length(message_ar) <= 500),
  message_en text not null check (char_length(trim(message_en)) > 0 and char_length(message_en) <= 500),
  link text check (link is null or char_length(link) <= 255),
  is_read boolean not null default false,
  created_at timestamptz not null default now()
);

create index if not exists customer_notifications_user_idx
  on public.customer_notifications (customer_id, created_at desc);

create index if not exists customer_notifications_unread_idx
  on public.customer_notifications (customer_id, is_read)
  where is_read = false;

alter table public.customer_notifications enable row level security;

drop policy if exists customer_notifications_select on public.customer_notifications;
create policy customer_notifications_select on public.customer_notifications
  for select
  to authenticated
  using (customer_id = auth.uid());

drop policy if exists customer_notifications_update on public.customer_notifications;
create policy customer_notifications_update on public.customer_notifications
  for update
  to authenticated
  using (customer_id = auth.uid())
  with check (customer_id = auth.uid());

drop policy if exists customer_notifications_delete on public.customer_notifications;
create policy customer_notifications_delete on public.customer_notifications
  for delete
  to authenticated
  using (customer_id = auth.uid());

revoke insert on public.customer_notifications from public, anon, authenticated;
grant select, update (is_read), delete on public.customer_notifications to authenticated;

-- Mark all notifications as read for current customer
create or replace function public.mark_all_notifications_read()
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501', hint = 'AUTH-001';
  end if;

  update public.customer_notifications
     set is_read = true
   where customer_id = auth.uid()
     and is_read = false;
end;
$$;

revoke all on function public.mark_all_notifications_read() from public, anon;
grant execute on function public.mark_all_notifications_read() to authenticated;

-- 2. Customer Suggestions Table
create table if not exists public.customer_suggestions (
  id uuid primary key default gen_random_uuid(),
  customer_id uuid references public.profiles (id) on delete set null,
  topic text not null check (topic in ('products', 'service', 'delivery', 'website', 'other')),
  message text not null check (char_length(trim(message)) >= 10 and char_length(message) <= 1000),
  status text not null default 'pending' check (status in ('pending', 'reviewed', 'archived')),
  admin_notes text check (admin_notes is null or char_length(admin_notes) <= 500),
  created_at timestamptz not null default now(),
  reviewed_at timestamptz
);

create index if not exists customer_suggestions_created_idx
  on public.customer_suggestions (created_at desc);

create index if not exists customer_suggestions_customer_idx
  on public.customer_suggestions (customer_id, created_at desc);

alter table public.customer_suggestions enable row level security;

drop policy if exists customer_suggestions_select on public.customer_suggestions;
create policy customer_suggestions_select on public.customer_suggestions
  for select
  to authenticated
  using (customer_id = auth.uid() or public.is_admin());

drop policy if exists customer_suggestions_admin_update on public.customer_suggestions;
create policy customer_suggestions_admin_update on public.customer_suggestions
  for update
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

revoke insert, update, delete on public.customer_suggestions from public, anon, authenticated;
grant select on public.customer_suggestions to authenticated;

-- Secure submission RPC for suggestions with rate limiting
create or replace function public.submit_customer_suggestion(
  p_topic text,
  p_message text
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid;
  v_recent_count integer;
  v_id uuid;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'Authentication required' using errcode = '42501', hint = 'AUTH-001';
  end if;

  if p_topic is null or p_topic not in ('products', 'service', 'delivery', 'website', 'other') then
    raise exception 'Invalid suggestion topic' using errcode = '22023', hint = 'SUG-002';
  end if;

  if p_message is null or char_length(trim(p_message)) < 10 or char_length(p_message) > 1000 then
    raise exception 'Suggestion message must be between 10 and 1000 characters' using errcode = '22023', hint = 'SUG-003';
  end if;

  -- Rate limit: maximum 5 suggestions per customer in the last hour
  select count(*)
    into v_recent_count
    from public.customer_suggestions
   where customer_id = v_uid
     and created_at > now() - interval '1 hour';

  if v_recent_count >= 5 then
    raise exception 'Too many suggestions submitted. Please try again later.'
      using errcode = '22023', hint = 'SUG-001';
  end if;

  insert into public.customer_suggestions (
    customer_id,
    topic,
    message
  ) values (
    v_uid,
    p_topic,
    trim(p_message)
  )
  returning id into v_id;

  return v_id;
end;
$$;

revoke all on function public.submit_customer_suggestion(text, text) from public, anon;
grant execute on function public.submit_customer_suggestion(text, text) to authenticated;

-- Admin review RPC for suggestions
create or replace function public.admin_review_suggestion(
  p_id uuid,
  p_status text,
  p_notes text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_old_status text;
begin
  perform public.require_admin();

  if p_status is null or p_status not in ('pending', 'reviewed', 'archived') then
    raise exception 'Invalid suggestion status' using errcode = '22023', hint = 'ADM-007';
  end if;

  if p_notes is not null and char_length(p_notes) > 500 then
    raise exception 'Admin notes exceed 500 characters' using errcode = '22023', hint = 'ADM-007';
  end if;

  select status into v_old_status
    from public.customer_suggestions
   where id = p_id;

  if v_old_status is null then
    raise exception 'Suggestion not found' using errcode = 'P0002', hint = 'SUG-004';
  end if;

  update public.customer_suggestions
     set status = p_status,
         admin_notes = p_notes,
         reviewed_at = case when p_status <> 'pending' then now() else null end
   where id = p_id;

  perform public.audit_event(
    'SUGGESTION_REVIEW',
    'customer_suggestions',
    p_id::text,
    jsonb_build_object('status', v_old_status),
    jsonb_build_object('status', p_status, 'notes', p_notes)
  );
end;
$$;

revoke all on function public.admin_review_suggestion(uuid, text, text) from public, anon;
grant execute on function public.admin_review_suggestion(uuid, text, text) to authenticated;

-- 3. Automatic Notifications: Order Approval Trigger
create or replace function public.notify_on_order_approved()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.user_id is not null and
     new.payment_status = 'awaiting_proof' and
     (old.payment_status is distinct from new.payment_status) then
    insert into public.customer_notifications (
      customer_id,
      type,
      title_ar,
      title_en,
      message_ar,
      message_en,
      link
    ) values (
      new.user_id,
      'order_approved',
      'تمت الموافقة على طلبك',
      'Your order has been approved',
      'تمت الموافقة على طلبك #' || new.id || '. يمكنك الآن تأكيد الدفع.',
      'Your order #' || new.id || ' has been approved. You can now submit payment proof.',
      '/pay/' || new.id
    );
  end if;
  return new;
end;
$$;

drop trigger if exists trg_notify_order_approved on public.orders;
create trigger trg_notify_order_approved
  after update of payment_status on public.orders
  for each row
  execute function public.notify_on_order_approved();

-- 4. Automatic Notifications: Wishlist Sale Trigger
create or replace function public.notify_on_wishlist_sale()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.is_active = true and
     new.discount_percent > 0 and
     (old.discount_percent is null or new.discount_percent > old.discount_percent) then
    insert into public.customer_notifications (
      customer_id,
      type,
      title_ar,
      title_en,
      message_ar,
      message_en,
      link
    )
    select
      f.user_id,
      'wishlist_sale',
      'عرض على منتج في مفضلتك',
      'Sale on wishlist item',
      'أصبح المنتج "' || coalesce(new.name_ar, new.name) || '" متوفرًا بخصم ' || new.discount_percent || '%!',
      'The product "' || coalesce(new.name, new.name_ar) || '" is now on sale with ' || new.discount_percent || '% off!',
      '/products/' || new.id
    from public.favorites f
    where f.product_id = new.id;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_notify_wishlist_sale on public.products;
create trigger trg_notify_wishlist_sale
  after update of discount_percent on public.products
  for each row
  execute function public.notify_on_wishlist_sale();

-- 5. Admin Broadcast Sale Notification RPC
create or replace function public.admin_broadcast_sale_notification(
  p_title_ar text,
  p_title_en text,
  p_message_ar text,
  p_message_en text,
  p_link text default null
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  perform public.require_admin();

  if p_title_ar is null or char_length(trim(p_title_ar)) = 0 or char_length(p_title_ar) > 120 or
     p_title_en is null or char_length(trim(p_title_en)) = 0 or char_length(p_title_en) > 120 or
     p_message_ar is null or char_length(trim(p_message_ar)) = 0 or char_length(p_message_ar) > 500 or
     p_message_en is null or char_length(trim(p_message_en)) = 0 or char_length(p_message_en) > 500 then
    raise exception 'Invalid notification payload' using errcode = '22023', hint = 'ADM-007';
  end if;

  if p_link is not null and char_length(p_link) > 255 then
    raise exception 'Notification link too long' using errcode = '22023', hint = 'ADM-007';
  end if;

  insert into public.customer_notifications (
    customer_id,
    type,
    title_ar,
    title_en,
    message_ar,
    message_en,
    link
  )
  select
    p.id,
    'general_sale',
    trim(p_title_ar),
    trim(p_title_en),
    trim(p_message_ar),
    trim(p_message_en),
    p_link
  from public.profiles p;

  get diagnostics v_count = row_count;

  perform public.audit_event(
    'BROADCAST_SALE_NOTIFICATION',
    'customer_notifications',
    'broadcast',
    null,
    jsonb_build_object('recipient_count', v_count, 'title_en', trim(p_title_en))
  );

  return v_count;
end;
$$;

revoke all on function public.admin_broadcast_sale_notification(text, text, text, text, text) from public, anon;
grant execute on function public.admin_broadcast_sale_notification(text, text, text, text, text) to authenticated;

-- 6. Admin Wishlist Demand Reporting RPC
create or replace function public.admin_get_wishlist_demand()
returns table (
  product_id bigint,
  product_name text,
  product_name_ar text,
  price numeric,
  discount_percent smallint,
  final_price numeric,
  stock_quantity integer,
  is_active boolean,
  image_url text,
  wishlist_count bigint
)
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.require_admin();

  return query
  select
    p.id as product_id,
    p.name as product_name,
    p.name_ar as product_name_ar,
    p.price,
    p.discount_percent,
    p.final_price,
    p.stock_quantity,
    p.is_active,
    p.image_url,
    count(f.user_id) as wishlist_count
  from public.products p
  inner join public.favorites f on f.product_id = p.id
  group by p.id, p.name, p.name_ar, p.price, p.discount_percent, p.final_price, p.stock_quantity, p.is_active, p.image_url
  order by wishlist_count desc, p.id desc;
end;
$$;

revoke all on function public.admin_get_wishlist_demand() from public, anon;
grant execute on function public.admin_get_wishlist_demand() to authenticated;

-- 1. Add avatar_url column to profiles
alter table public.profiles
  add column if not exists avatar_url text;

-- 2. Constraints on profiles.avatar_url
alter table public.profiles
  drop constraint if exists profiles_avatar_url_length;
alter table public.profiles
  add constraint profiles_avatar_url_length
  check (avatar_url is null or char_length(avatar_url) <= 300);

alter table public.profiles
  drop constraint if exists profiles_avatar_url_path;
alter table public.profiles
  add constraint profiles_avatar_url_path
  check (avatar_url is null or avatar_url ~ '^[0-9a-fA-F-]{36}/[A-Za-z0-9/_-]+\.(webp|jpg|jpeg|png)$');

-- 3. Grant column update permissions to authenticated role
grant update (avatar_url) on public.profiles to authenticated;

-- 4. User folder integrity trigger:
-- Ensures avatar_url belongs to the profile's own user ID folder
create or replace function public.validate_profile_avatar()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if new.avatar_url is not null then
    if split_part(new.avatar_url, '/', 1) <> new.id::text then
      raise exception 'Avatar path must match user ID: %', new.id
        using errcode = '23514', hint = 'SEC-001';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_validate_profile_avatar on public.profiles;
create trigger trg_validate_profile_avatar
  before insert or update on public.profiles
  for each row
  execute function public.validate_profile_avatar();

-- 5. Storage bucket 'avatars' with 2 MB limit and allowed image MIME types
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'avatars',
  'avatars',
  true,
  2097152, -- 2 MB limit
  array['image/jpeg', 'image/png', 'image/webp']
)
on conflict (id) do update
  set public = true,
      file_size_limit = 2097152,
      allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp'];

-- 6. Storage RLS policies for 'avatars' bucket
-- 6a. Public read access
drop policy if exists "public read avatars" on storage.objects;
create policy "public read avatars" on storage.objects
  for select
  using (bucket_id = 'avatars');

-- 6b. User-owned upload (INSERT)
drop policy if exists "user upload avatar" on storage.objects;
create policy "user upload avatar" on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

-- 6c. User-owned update (UPDATE)
drop policy if exists "user update avatar" on storage.objects;
create policy "user update avatar" on storage.objects
  for update to authenticated
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  )
  with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

-- 6d. User delete avatar (DELETE) - owner or admin
drop policy if exists "user delete avatar" on storage.objects;
create policy "user delete avatar" on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'avatars'
    and (
      (storage.foldername(name))[1] = (select auth.uid())::text
      or public.is_admin()
    )
  );

-- 7. Automated replacement cleanup trigger:
-- When a user changes or removes their avatar_url, purge the old storage object
create or replace function public.cleanup_old_avatar()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if old.avatar_url is not null and (new.avatar_url is null or new.avatar_url <> old.avatar_url) then
    delete from storage.objects
     where bucket_id = 'avatars'
       and name = old.avatar_url;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_cleanup_old_avatar on public.profiles;
create trigger trg_cleanup_old_avatar
  after update on public.profiles
  for each row
  execute function public.cleanup_old_avatar();

